import XCTest
import Foundation
import Darwin
@testable import VunemiHelper
final class NativeFileMoveTests:XCTestCase{
 func fixture()throws->(URL,URL,URL){let dir=FileManager.default.temporaryDirectory.appendingPathComponent("file-move-"+UUID().uuidString);try FileManager.default.createDirectory(at:dir.appendingPathComponent("to"),withIntermediateDirectories:true);let src=dir.appendingPathComponent("source.txt"),dst=dir.appendingPathComponent("to/result.txt");try Data("owned bytes".utf8).write(to:src);addTeardownBlock{try? FileManager.default.removeItem(at:dir)};return(dir,src,dst)}
 func request(_ s:URL,_ d:URL)throws->JSON{try fileMoveTestRequest(source:s.path,destination:d.path)}
 func testRealNoClobberRenameAndIndependentIdentity()throws{let(_,s,d)=try fixture();let result=safeFileMove(try request(s,d));XCTAssertEqual(result["status"] as? String,"moved",String(describing:result));XCTAssertFalse(FileManager.default.fileExists(atPath:s.path));XCTAssertEqual(try String(contentsOf:d,encoding:.utf8),"owned bytes")}
 func testDestinationRaceNoOverwrite()throws{let(_,s,d)=try fixture();let args=try request(s,d);let result=safeFileMove(args,beforeRename:{try Data("keep".utf8).write(to:d)});XCTAssertEqual(result["status"] as? String,"not-moved");XCTAssertEqual(try String(contentsOf:d,encoding:.utf8),"keep");XCTAssertTrue(FileManager.default.fileExists(atPath:s.path))}
 func testStaleSourceAndParentSymlinkRefuse()throws{let(dir,s,d)=try fixture();let args=try request(s,d);try Data("changed".utf8).write(to:s);XCTAssertEqual(safeFileMove(args)["status"] as? String,"not-moved");let fresh=try request(s,d);try FileManager.default.moveItem(at:dir.appendingPathComponent("to"),to:dir.appendingPathComponent("old"));try FileManager.default.createSymbolicLink(atPath:dir.appendingPathComponent("to").path,withDestinationPath:dir.appendingPathComponent("old").path);XCTAssertEqual(safeFileMove(fresh)["status"] as? String,"not-moved");XCTAssertTrue(FileManager.default.fileExists(atPath:s.path))}
 func testPrecommitStopNoEffectAndPostcommitFailureUnknown()throws{let(_,s,d)=try fixture();let args=try request(s,d);let stopped=safeFileMove(args,beforeRename:{throw NSError(domain:"stopped",code:1)});XCTAssertEqual(stopped["status"] as? String,"not-moved");XCTAssertTrue(FileManager.default.fileExists(atPath:s.path));XCTAssertFalse(FileManager.default.fileExists(atPath:d.path));let committed=safeFileMove(args,afterRename:{throw NSError(domain:"simulated-durability-loss",code:1)});XCTAssertEqual(committed["status"] as? String,"unknown");XCTAssertFalse(FileManager.default.fileExists(atPath:s.path));XCTAssertEqual(try String(contentsOf:d,encoding:.utf8),"owned bytes")}
 func testSourceSymlinkRefused()throws{let(dir,s,d)=try fixture();let args=try request(s,d);try FileManager.default.moveItem(at:s,to:dir.appendingPathComponent("old-source"));try FileManager.default.createSymbolicLink(atPath:s.path,withDestinationPath:dir.appendingPathComponent("old-source").path);XCTAssertEqual(safeFileMove(args)["status"] as? String,"not-moved");XCTAssertFalse(FileManager.default.fileExists(atPath:d.path))}
 func testMalformedRequestNoEffect()throws{let(_,s,d)=try fixture();XCTAssertEqual(safeFileMove([:])["status"] as? String,"not-moved");var r=try request(s,d);r["destination"]="/tmp/../outside";XCTAssertEqual(safeFileMove(r)["status"] as? String,"not-moved");XCTAssertTrue(FileManager.default.fileExists(atPath:s.path))}
}

private func fileMoveTestRequest(source:String,destination:String)throws->JSON{
 func canonical(_ p:String)throws->String{guard let pointer=realpath(p,nil) else{throw NSError(domain:"realpath",code:1)};defer{free(pointer)};return String(cString:pointer)}
 let s=try canonical(source),d=try canonical((destination as NSString).deletingLastPathComponent)+"/"+(destination as NSString).lastPathComponent
 func parents(_ path:String)throws->[JSON]{var values:[JSON]=[];var at=(path as NSString).deletingLastPathComponent;while true{var st=stat();guard lstat(at,&st)==0 else{throw NSError(domain:"stat",code:1)};values.append(["path":at,"device":String(st.st_dev),"inode":String(st.st_ino),"uid":Int(st.st_uid),"mode":Int(st.st_mode)]);if at=="/"{break};at=(at as NSString).deletingLastPathComponent};return values.reversed()}
 let fd=open(s,O_RDONLY|O_NOFOLLOW);guard fd>=0 else{throw NSError(domain:"open",code:1)};defer{close(fd)}
 return ["operationId":UUID().uuidString,"ownerId":"test-owner","source":s,"destination":d,"sourceIdentity":try fileMoveIdentity(fd),"sourceParents":try parents(s),"destinationParents":try parents(d)]
}
